package com.exampro.controller;import com.exampro.dto.ApiDtos.*;import com.exampro.service.QuestionService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class QuestionController {private final QuestionService s;public QuestionController(QuestionService s){this.s=s;}@GetMapping("/questions") public List<QuestionResponse> all(){return s.all();}@GetMapping("/questions/{id}") public QuestionResponse get(@PathVariable Long id){return s.get(id);}@GetMapping("/admin/questions") public List<AdminQuestionResponse> adminAll(){return s.adminAll();}@GetMapping("/admin/questions/{id}") public AdminQuestionResponse adminGet(@PathVariable Long id){return s.adminGet(id);}@PostMapping("/admin/questions") public ResponseEntity<QuestionResponse> create(@Valid @RequestBody QuestionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@PutMapping("/admin/questions/{id}") public QuestionResponse update(@PathVariable Long id,@Valid @RequestBody QuestionRequest r){return s.update(id,r);}@DeleteMapping("/admin/questions/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
